mapper.insert:
INSERT INTO erp_time_table
(yy, mm, dayname, period_no, start_time, end_time, class_key, unit_key, grade_key, user_code, created_at, time_table_key)
values (#{yy}, #{mm}, #{dayname}, #{periodNo}, #{startTime}, #{endTime}, #{classKey}, #{unitKey}, #{gradeKey}, #{userCode}, CURRENT_TIMESTAMP, #{timeTableKey});

INSERT INTO erp_time_table_assign
    (student_id, time_table_key, week)
values (#{studentId}, #{timeTableKey}, #{weekNo});

INSERT INTO erp_monthly_score
(question1, question2, question3, question4, question5, question6, question7, question8, student_id, yy, mm, time_table_key, created_at)
VALUES (0, 0, 0, 0, 0, 0, 0, 0, #{studentId}, #{yy}, #{mm}, #{timeTableKey}, CURRENT_TIMESTAMP);

mapper.select:
SELECT COUNT(*)
FROM erp_time_table_assign
WHERE time_table_key = #{timeTableKey}

mapper.delete:
DELETE
FROM erp_time_table_assign
WHERE time_table_key = #{timeTableKey}
  AND student_id = #{studentId}

mapper.insert:
INSERT INTO erp_time_table_code
    (time_table_key, time_table_label, time_table_ym)
values (#{timeTableKey}, #{timeTableLabel}, #{timeTableYm});

mapper.select:
SELECT
tc.time_table_key as timeTableKey,
tc.time_table_label as classLabel
FROM ERP_TIME_TABLE t
JOIN ERP_TIME_TABLE_CODE tc
ON t.time_table_key = tc.time_table_key
WHERE YY = #{yy}
AND MM = #{mm}

    AND t.user_code = #{userCode}

ORDER BY CHARINDEX(dayname, 'mon,tue,wed,thu,fri,sat,sun');

SELECT t.time_table_key    as timeTableKey,
       tc.time_table_label as classLabel,
       t.class_key         as classKey,
       t.unit_key          as unitKey
FROM erp_time_table t
         JOIN erp_time_table_code tc ON t.time_table_key = tc.time_table_key
WHERE yy = #{yy}
  AND mm = #{mm}
  AND dayName = #{dayName}

    AND user_code = #{userCode}

ORDER BY t.period_no ASC

SELECT COUNT(*)
FROM erp_student_attendance
WHERE student_id = #{studentId}
